import{_ as t,o as r,c as o,ak as a}from"./chunks/framework.BNVJvTzl.js";const p=JSON.parse('{"title":"Importing from Harvest","description":"","frontmatter":{},"headers":[],"relativePath":"reference/workflows/harvest-import.md","filePath":"reference/workflows/harvest-import.md"}'),s={name:"reference/workflows/harvest-import.md"};function n(i,e,h,d,l,c){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="importing-from-harvest" tabindex="-1">Importing from Harvest <a class="header-anchor" href="#importing-from-harvest" aria-label="Permalink to &quot;Importing from Harvest&quot;">​</a></h1><p>How to bring a client&#39;s Harvest history into VERA, so their projects, people and past time are here from day one.</p><hr><h2 id="what-comes-across" tabindex="-1">What comes across <a class="header-anchor" href="#what-comes-across" aria-label="Permalink to &quot;What comes across&quot;">​</a></h2><ul><li><strong>Active projects</strong> from Harvest. Archived projects are left behind.</li><li><strong>Clients, people and tasks</strong> those projects use.</li><li><strong>People&#39;s cost rates</strong>, from the rates Harvest recorded on their time.</li><li><strong>Time</strong>, every entry on the imported projects.</li><li><strong>Invoiced amounts</strong>, used for a retainer&#39;s history. A retainer&#39;s earlier time becomes a finished fixed-price project priced at what Harvest invoiced for it, and its recent time goes on a real retainer.</li></ul><p>You do it yourself, as an owner or admin, from <strong>Settings → Import</strong>.</p><hr><h2 id="the-five-steps" tabindex="-1">The five steps <a class="header-anchor" href="#the-five-steps" aria-label="Permalink to &quot;The five steps&quot;">​</a></h2><ol><li><strong>Connect.</strong> Create a personal access token in Harvest under Developers, then enter it with your Harvest account ID. VERA uses it once to read your data and does not keep it.</li><li><strong>Review.</strong> VERA suggests what each Harvest project should become (a retainer, hourly, fixed price, pro bono, internal, or skipped) and lists anything it could not decide. Fix the terms in the table, then save.</li><li><strong>Dry run.</strong> A table shows what would be created and the hours for each project, so you can check the totals against Harvest before anything is written.</li><li><strong>Run.</strong> The import runs in the background and shows its progress. Leaving the page does not stop it.</li><li><strong>Result.</strong> The page reports how many time entries were written, and whether every project&#39;s hours match Harvest.</li></ol><p>Your draft is kept for two hours. If it runs out, connect again.</p><hr><h2 id="what-the-flags-mean" tabindex="-1">What the flags mean <a class="header-anchor" href="#what-the-flags-mean" aria-label="Permalink to &quot;What the flags mean&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Flag</th><th>What it means</th><th>What to do</th></tr></thead><tbody><tr><td>Fixed-fee project with no fee</td><td>Harvest has no fee and nothing invoiced for it</td><td>Enter its contract value</td></tr><tr><td>Retainer terms missing</td><td>Monthly hours or fee could not be found</td><td>Enter the hours and the fee per month</td></tr><tr><td>Several monthly amounts</td><td>The notes name more than one monthly amount, so VERA added them</td><td>Check the total is the real monthly fee</td></tr><tr><td>Time before the retainer started</td><td>Time was recorded before the retainer&#39;s start month</td><td>Decide whether to move it; VERA does not guess</td></tr><tr><td>Possible duplicate person</td><td>Two names differ only by a trailing note in parentheses and were merged</td><td>Remove the merge if they are different people</td></tr><tr><td>Shared account</td><td>A name that looks like a shared login</td><td>Check the time was reassigned to the right people</td></tr><tr><td>Zero cost rate</td><td>Someone has time costed at $0</td><td>Give them a rate</td></tr></tbody></table><hr><h2 id="undo" tabindex="-1">Undo <a class="header-anchor" href="#undo" aria-label="Permalink to &quot;Undo&quot;">​</a></h2><p>If something is wrong, <strong>Undo</strong> on the latest import removes everything it created. VERA refuses, and lists why, if anything has changed since the import, such as an edited project or new time recorded on it. Fix or accept what it lists, then try again.</p>',16)])])}const f=t(s,[["render",n]]);export{p as __pageData,f as default};
